def getTokenPrice(token, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0083000" if __import__("os").path.isdir("./environment_mix/0083000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _log(tool_name, request_params, status_code, latency_ms, resolved_token_id=None, error_code=None):
        logs = _load("api_request_logs.json")
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "resolved_token_id": resolved_token_id,
            "response_status_code": int(status_code),
            "latency_ms": int(max(0, min(300000, latency_ms))),
            "error_code": error_code,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(row)
        _save("api_request_logs.json", logs)

    # Simple service-wide rate limit: 120 requests/min across all tools (observed via logs)
    def _enforce_rate_limit():
        logs = _load("api_request_logs.json")
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window_start:
                cnt += 1
        if cnt >= 120:
            return False, cnt
        return True, cnt

    ok_rl, rl_cnt = _enforce_rate_limit()
    if not ok_rl:
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 429, latency, resolved_token_id=None, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120, recent_requests=rl_cnt)

    # Validation
    if not isinstance(token, str):
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 400, latency, resolved_token_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`token` must be a string.")
    norm = token.strip().upper()
    if not norm:
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 400, latency, resolved_token_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`token` is required and cannot be empty.")
    if not re.fullmatch(r"[A-Z0-9][A-Z0-9\-\.]{0,19}", norm):
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 400, latency, resolved_token_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported token symbol format.")

    tokens = _load("tokens.json")

    def _match_token(sym):
        needle = sym.strip().upper()
        needle_l = needle.lower()
        for r in tokens:
            rs = r.get("symbol")
            if isinstance(rs, str) and rs.strip().upper() == needle:
                return r
        for r in tokens:
            aliases = r.get("aliases")
            if isinstance(aliases, list):
                for a in aliases:
                    if isinstance(a, str) and a.strip().lower() == needle_l:
                        return r
        return None

    tok = _match_token(norm)
    if not tok:
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 404, latency, resolved_token_id=None, error_code="TOKEN_NOT_FOUND")
        return _err("NOT_FOUND", "Token not found.", error_code="TOKEN_NOT_FOUND")

    token_id = tok.get("id")

    snaps = _load("token_price_snapshots.json")
    candidates = []
    for s in snaps:
        if s.get("token_id") != token_id:
            continue
        if s.get("status") != "valid":
            continue
        qc = s.get("quote_currency")
        if qc not in ("USDT", "USD"):
            continue
        as_of = _parse_dt(s.get("as_of"))
        if not as_of:
            continue
        candidates.append((as_of, s))
    if not candidates:
        latency = int((time.time() - t0) * 1000)
        _log("getTokenPrice", {"token": token}, 404, latency, resolved_token_id=token_id, error_code="NO_PRICE_SNAPSHOT")
        return _err("NOT_FOUND", "No price snapshot available for this token.", error_code="NO_PRICE_SNAPSHOT")

    candidates.sort(key=lambda x: x[0], reverse=True)
    as_of, snap = candidates[0]

    # Application-layer staleness marking (do not mutate snapshot here)
    staleness_threshold = datetime.timedelta(minutes=5)
    is_stale = (now - as_of) > staleness_threshold

    resp = {
        "token": norm,
        "token_id": token_id,
        "quote_currency": snap.get("quote_currency"),
        "price": snap.get("price"),
        "source": snap.get("source"),
        "as_of": snap.get("as_of"),
        "snapshot_status": snap.get("status"),
        "stale": bool(is_stale),
    }

    latency = int((time.time() - t0) * 1000)
    _log("getTokenPrice", {"token": token}, 200, latency, resolved_token_id=token_id, error_code=None)
    return {"data": resp}

