def listTokens(query=None, status=None, is_spot_supported=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0083000" if __import__("os").path.isdir("./environment_mix/0083000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _log(tool_name, request_params, status_code, latency_ms, resolved_token_id=None, error_code=None):
        logs = _load("api_request_logs.json")
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,  # not in api_request_logs enum; keep logging best-effort by storing anyway
            "request_params": request_params if isinstance(request_params, dict) else {},
            "resolved_token_id": resolved_token_id,
            "response_status_code": int(status_code),
            "latency_ms": int(max(0, min(300000, latency_ms))),
            "error_code": error_code,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(row)
        _save("api_request_logs.json", logs)

    # Rate limit: 120 req/min
    def _enforce_rate_limit():
        logs = _load("api_request_logs.json")
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window_start:
                cnt += 1
        if cnt >= 120:
            return False, cnt
        return True, cnt

    ok_rl, rl_cnt = _enforce_rate_limit()
    if not ok_rl:
        latency = int((time.time() - t0) * 1000)
        _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 429, latency, None, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120, recent_requests=rl_cnt)

    # Validation
    if query is not None and not isinstance(query, str):
        latency = int((time.time() - t0) * 1000)
        _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`query` must be a string when provided.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive", "delisted"):
            latency = int((time.time() - t0) * 1000)
            _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`status` must be one of: active, inactive, delisted.")
    if is_spot_supported is not None and not isinstance(is_spot_supported, bool):
        latency = int((time.time() - t0) * 1000)
        _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`is_spot_supported` must be a boolean when provided.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        latency = int((time.time() - t0) * 1000)
        _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be an integer.")
    if limit < 1 or limit > 200:
        latency = int((time.time() - t0) * 1000)
        _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.")

    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            latency = int((time.time() - t0) * 1000)
            _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`cursor` must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("sym:"):
                raise ValueError("bad cursor")
            start_after = raw[4:]
        except Exception:
            latency = int((time.time() - t0) * 1000)
            _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 400, latency, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    tokens = _load("tokens.json")

    q = (query or "").strip().lower()
    def _matches(t):
        if status is not None and t.get("status") != status:
            return False
        if is_spot_supported is not None and t.get("is_spot_supported") is not is_spot_supported:
            return False
        if q:
            sym = (t.get("symbol") or "")
            name = (t.get("name") or "")
            aliases = t.get("aliases") if isinstance(t.get("aliases"), list) else []
            hay = [sym, name] + [a for a in aliases if isinstance(a, str)]
            if not any(q in (h or "").lower() for h in hay):
                return False
        return True

    filtered = [t for t in tokens if isinstance(t, dict) and _matches(t)]
    filtered.sort(key=lambda r: ((r.get("symbol") or "").upper(), (r.get("id") or "")))

    if start_after is not None:
        sa = start_after.upper()
        filtered = [r for r in filtered if ((r.get("symbol") or "").upper() > sa)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last_sym = (page[-1].get("symbol") or "").upper()
        next_cursor = base64.urlsafe_b64encode(f"sym:{last_sym}".encode("utf-8")).decode("utf-8").rstrip("=")

    latency = int((time.time() - t0) * 1000)
    _log("listTokens", {"query": query, "status": status, "is_spot_supported": is_spot_supported, "limit": limit, "cursor": cursor}, 200, latency, None, None)

    return {
        "data": {
            "tokens": page,
            "total": len(filtered),
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "limit": limit,
        }
    }

def getToken(id, **_extra):
