    # Validation
    if not isinstance(id, str) or not id.strip():
        # No api_request_logs entry for non-enum tool per schema; return error
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.")

    tokens = _load("tokens.json")
    tok = None
    for r in tokens:
        if isinstance(r, dict) and r.get("id") == id:
            tok = r
            break

    if tok is None:
        return _err("NOT_FOUND", "Token not found.", id=id)

    return {"token": tok}

def upsertToken(symbol, name, id=None, aliases=None, is_spot_supported=None, transfer=None, status=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0083000" if __import__("os").path.isdir("./environment_mix/0083000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    # Basic validation
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "Parameter 'symbol' must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "Parameter 'name' must be a non-empty string.")
    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string when provided.")

    sym_up = symbol.strip().upper()
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "Parameter 'status' must be a string.")
        if status not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "Invalid 'status'.", allowed=["active", "inactive", "delisted"])
    if aliases is not None:
        if not isinstance(aliases, list):
            return _err("VALIDATION_ERROR", "Parameter 'aliases' must be an array of strings.")
        norm_aliases = []
        seen = set()
        for a in aliases:
            if not isinstance(a, str) or not a.strip():
                return _err("VALIDATION_ERROR", "All aliases must be non-empty strings.")
            al = a.strip().lower()
            if al in seen:
                return _err("VALIDATION_ERROR", "Aliases must be unique (case-insensitive).", duplicate=al)
            seen.add(al)
            norm_aliases.append(al)
        aliases = norm_aliases
    if is_spot_supported is not None and not isinstance(is_spot_supported, bool):
        return _err("VALIDATION_ERROR", "Parameter 'is_spot_supported' must be a boolean.")
    if transfer is not None and not isinstance(transfer, (dict, bool)):
        # schema says boolean, but tool param says object; accept dict, and also accept bool for compatibility
        return _err("VALIDATION_ERROR", "Parameter 'transfer' must be an object.")
    # Load stores
    tokens = _load("tokens.json")
    chain_support = _load("token_chain_support.json")

    # Find existing by id if provided
    existing = None
    existing_idx = None
    if id is not None:
        for i, r in enumerate(tokens):
            if isinstance(r, dict) and r.get("id") == id:
                existing = r
                existing_idx = i
                break

    # Enforce unique(lower(symbol))
    for r in tokens:
        if not isinstance(r, dict):
            continue
        if existing is not None and r.get("id") == existing.get("id"):
            continue
        rs = r.get("symbol")
        if isinstance(rs, str) and rs.strip().lower() == sym_up.lower():
            return _err("CONFLICT", "A token with this symbol already exists.", symbol=sym_up)

    # Determine create vs update and apply lifecycle transition validation
    transitions = {
        "active": {"inactive", "delisted"},
        "inactive": {"active", "delisted"},
        "delisted": set()
    }

    if existing is None:
        # Create
        new_id = id.strip() if id is not None else f"tok_{uuid.uuid4().hex}"
        # ensure id uniqueness
        for r in tokens:
            if isinstance(r, dict) and r.get("id") == new_id:
                return _err("CONFLICT", "Token id already exists.", id=new_id)

        st = status if status is not None else "active"
        if st not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "Invalid 'status'.", allowed=["active", "inactive", "delisted"])

        # Constraint: delisted coins should not be is_spot_supported=true
        if st == "delisted" and is_spot_supported is True:
            return _err("VALIDATION_ERROR", "Delisted tokens cannot be spot supported.", status=st, is_spot_supported=True)

        created = now.isoformat()
        rec = {
            "id": new_id,
            "symbol": sym_up,
            "name": name,
            "aliases": aliases if aliases is not None else [],
            "is_spot_supported": bool(is_spot_supported) if is_spot_supported is not None else False,
            "transfer": bool(transfer) if isinstance(transfer, bool) else (transfer if transfer is not None else False),
            "status": st,
            "created_at": created,
            "updated_at": created
        }
        tokens.append(rec)
        _save("tokens.json", tokens)
        return {"token": rec, "created": True}
    else:
        # Update
        # Refuse attempts to modify immutable identifiers (id itself). Since id locates record, no change allowed.
        # (symbol is mutable but unique; enforce canonical casing)
        prev_status = existing.get("status")
        next_status = status if status is not None else prev_status

        if prev_status is None or prev_status not in transitions:
            return _err("VALIDATION_ERROR", "Existing token has invalid stored status.", status=prev_status)

        if next_status != prev_status:
            if next_status not in transitions.get(prev_status, set()):
                return _err("VALIDATION_ERROR", "Invalid status transition.", from_status=prev_status, to_status=next_status)

        # Constraint: delisted coins should not be is_spot_supported=true
        effective_is_spot = existing.get("is_spot_supported") if is_spot_supported is None else is_spot_supported
        if next_status == "delisted" and effective_is_spot is True:
            return _err("VALIDATION_ERROR", "Delisted tokens cannot be spot supported.", status=next_status, is_spot_supported=True)

        # Apply updates
        updated = dict(existing)
        updated["symbol"] = sym_up
        updated["name"] = name
        if aliases is not None:
            updated["aliases"] = aliases
        if is_spot_supported is not None:
            updated["is_spot_supported"] = is_spot_supported
        if transfer is not None:
            updated["transfer"] = bool(transfer) if isinstance(transfer, bool) else transfer
        if status is not None:
            updated["status"] = next_status

        # Enforce created_at <= updated_at (and keep created_at stable)
        created_at = updated.get("created_at")
        try:
            # If stored created_at is invalid, normalize to now to avoid breaking constraint
            _ = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00")) if isinstance(created_at, str) else None
        except Exception:
            created_at = now.isoformat()
            updated["created_at"] = created_at

        updated["updated_at"] = now.isoformat()

        # Additional business rule on write (token_chain_support must not exist for delisted unless disabled)
        if updated.get("status") == "delisted":
            tid = updated.get("id")
            for csr in chain_support:
                if not isinstance(csr, dict):
                    continue
                if csr.get("token_id") == tid and csr.get("status") != "disabled":
                    return _err(
                        "VALIDATION_ERROR",
                        "Cannot delist token while chain support rows are enabled; disable them first.",
                        token_id=tid
                    )

        tokens[existing_idx] = updated
        _save("tokens.json", tokens)
        return {"token": updated, "created": False}

def listAnnouncements(anType=None, status=None, published_from=None, published_to=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0083000" if __import__("os").path.isdir("./environment_mix/0083000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    # Validation
    allowed_types = {
        "latest_news",
        "coin_listings",
        "trading_competitions_promotions",
        "maintenance_system_updates",
        "symbol_delisting",
    }
    allowed_status = {"published", "retracted", "archived"}

    if anType is not None:
        if not isinstance(anType, str):
            return _err("VALIDATION_ERROR", "Parameter 'anType' must be a string.")
        if anType not in allowed_types:
            return _err("VALIDATION_ERROR", "Invalid 'anType'.", allowed=sorted(list(allowed_types)))

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "Parameter 'status' must be a string.")
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid 'status'.", allowed=sorted(list(allowed_status)))

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"Parameter '{field}' must be an ISO date-time string.")
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return _err("VALIDATION_ERROR", f"Parameter '{field}' must be a valid ISO date-time.", value=s)

    pf = _parse_dt(published_from, "published_from")
    if isinstance(pf, dict) and "error" in pf:
        return pf
    pt = _parse_dt(published_to, "published_to")
    if isinstance(pt, dict) and "error" in pt:
        return pt
    if pf and pt and pf > pt:
        return _err("VALIDATION_ERROR", "'published_from' must be <= 'published_to'.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be between 1 and 200.")

    # Cursor decode: base64 JSON {"published_at": "...", "id":"..."}
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "Parameter 'cursor' must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if "published_at" not in cursor_obj or "id" not in cursor_obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    anns = _load("announcements.json")

    # Filter
    def _to_dt(v):
        try:
            if isinstance(v, str):
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None
        return None

    rows = []
    for a in anns:
        if not isinstance(a, dict):
            continue
        if anType is not None and a.get("anType") != anType:
            continue
        if status is not None and a.get("status") != status:
            continue
        pdt = _to_dt(a.get("published_at"))
        if pdt is None:
            continue
        if pf is not None and pdt < pf:
            continue
        if pt is not None and pdt > pt:
            continue
        rows.append(a)

    # Sort published_at desc, tie-breaker id desc (stable)
    rows.sort(key=lambda r: (_to_dt(r.get("published_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(r.get("id") or "")), reverse=True)

    # Apply cursor (exclusive)
    if cursor_obj is not None:
        c_dt = _to_dt(cursor_obj.get("published_at"))
        c_id = str(cursor_obj.get("id"))
        if c_dt is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        filtered = []
        for r in rows:
            rdt = _to_dt(r.get("published_at"))
            rid = str(r.get("id") or "")
            if rdt is None:
                continue
            # since sorted desc, include items strictly "after" cursor in list (i.e., older than cursor)
            if rdt < c_dt or (rdt == c_dt and rid < c_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"published_at": last.get("published_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "announcements": page,
        "meta": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def upsertAnnouncement(anType, title, published_at, source, status, id=None, body=None, url=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0083000" if __import__("os").path.isdir("./environment_mix/0083000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    # Validate required
    allowed_types = {
        "latest_news",
        "coin_listings",
        "trading_competitions_promotions",
        "maintenance_system_updates",
        "symbol_delisting",
    }
    allowed_status = {"published", "retracted", "archived"}

    if not isinstance(anType, str) or anType not in allowed_types:
        return _err("VALIDATION_ERROR", "Invalid 'anType'.", allowed=sorted(list(allowed_types)))
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "Parameter 'title' must be a non-empty string.")
    if not isinstance(source, str) or not source.strip():
        return _err("VALIDATION_ERROR", "Parameter 'source' must be a non-empty string.")
    if not isinstance(status, str) or status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid 'status'.", allowed=sorted(list(allowed_status)))

    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string when provided.")
    if body is not None and not isinstance(body, str):
        return _err("VALIDATION_ERROR", "Parameter 'body' must be a string.")
    if url is not None and not isinstance(url, str):
        return _err("VALIDATION_ERROR", "Parameter 'url' must be a string.")

    if not isinstance(published_at, str) or not published_at.strip():
        return _err("VALIDATION_ERROR", "Parameter 'published_at' must be an ISO date-time string.")
    try:
        pdt = datetime.datetime.fromisoformat(published_at.replace("Z", "+00:00"))
    except Exception:
        return _err("VALIDATION_ERROR", "Parameter 'published_at' must be a valid ISO date-time.", value=published_at)

    # Business rule: published_at not more than 24h in the future relative to ingestion
    # (allow naive dt treated as UTC)
    if pdt.tzinfo is None:
        pdt = pdt.replace(tzinfo=datetime.timezone.utc)
    if pdt > (now + datetime.timedelta(hours=24)):
        return _err("VALIDATION_ERROR", "published_at is unreasonably far in the future (>24h).", published_at=published_at)

    anns = _load("announcements.json")

    # Find existing by id if provided
    existing = None
    existing_idx = None
    if id is not None:
        for i, r in enumerate(anns):
            if isinstance(r, dict) and r.get("id") == id:
                existing = r
                existing_idx = i
                break

    # Dedupe constraint: unique(source, url) where url not null
    if url is not None and url.strip():
        for r in anns:
            if not isinstance(r, dict):
                continue
            if existing is not None and r.get("id") == existing.get("id"):
                continue
            if r.get("source") == source and r.get("url") == url:
                return _err("CONFLICT", "Announcement with same (source, url) already exists.", source=source, url=url)

    transitions = {
        "published": {"archived", "retracted"},
        "archived": {"retracted"},
        "retracted": set()
    }

    if existing is None:
        new_id = id.strip() if id is not None else f"ann_{uuid.uuid4().hex}"
        for r in anns:
            if isinstance(r, dict) and r.get("id") == new_id:
                return _err("CONFLICT", "Announcement id already exists.", id=new_id)

        created = now.isoformat()
        rec = {
            "id": new_id,
            "anType": anType,
            "title": title,
            "body": body if body is not None else None,
            "url": url if url is not None else None,
            "published_at": pdt.isoformat(),
            "source": source,
            "status": status,
            "created_at": created,
            "updated_at": created
        }
        anns.append(rec)
        _save("announcements.json", anns)
        return {"announcement": rec, "created": True}
    else:
        prev_status = existing.get("status")
        if prev_status not in transitions:
            return _err("VALIDATION_ERROR", "Existing announcement has invalid stored status.", status=prev_status)
        if status != prev_status:
            if status not in transitions.get(prev_status, set()):
                return _err("VALIDATION_ERROR", "Invalid status transition.", from_status=prev_status, to_status=status)

        updated = dict(existing)
        updated["anType"] = anType
        updated["title"] = title
        updated["published_at"] = pdt.isoformat()
        updated["source"] = source
        updated["status"] = status
        if body is not None:
            updated["body"] = body
        if url is not None:
            updated["url"] = url

        # Keep created_at stable; update updated_at
        created_at = updated.get("created_at")
        try:
            _ = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00")) if isinstance(created_at, str) else None
        except Exception:
            updated["created_at"] = now.isoformat()
        updated["updated_at"] = now.isoformat()

        anns[existing_idx] = updated
        _save("announcements.json", anns)
        return {"announcement": updated, "created": False}
